import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';

const RobotScene = () => {
    const mountRef = useRef(null);

    // --- NASTAVENÍ (Tady ladíme pohled) ---

    // 1. OTOČENÍ HLAVY O 180 STUPŇŮ (Fix pro "koukání dozadu")
    const HEAD_Y_OFFSET = Math.PI;

    // 2. SKLON HLAVY (Nahoru / Dolů)
    // ZMĚNA: Nastaveno na -0.3, aby se díval rovně a nebyl zakloněný
    const HEAD_X_OFFSET = -0.3; 
    
    // 3. LIMIT POHYBU
    // Jak moc do stran může kroutit hlavou
    const LOOK_LIMIT = 0.5; 

    // ---------------------------------------

    useEffect(() => {
        const width = window.innerWidth;
        const height = window.innerHeight;

        const scene = new THREE.Scene();

        const camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 1000);
        camera.position.set(0, 0, 7);

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(width, height);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.2;
        
        const currentRef = mountRef.current;
        if (currentRef) {
            while (currentRef.firstChild) {
                currentRef.removeChild(currentRef.firstChild);
            }
            currentRef.appendChild(renderer.domElement);
        }

        const ambientLight = new THREE.AmbientLight(0xffffff, 0.8);
        scene.add(ambientLight);

        const mainLight = new THREE.DirectionalLight(0xffffff, 3);
        mainLight.position.set(2, 2, 5); 
        scene.add(mainLight);

        const rimLight = new THREE.DirectionalLight(0x0077ff, 2);
        rimLight.position.set(-5, 0, 2);
        scene.add(rimLight);

        let mixer;
        let headObject;
        const loader = new GLTFLoader();

        loader.load('/Samurai.glb', (gltf) => {
            const model = gltf.scene;

            model.scale.set(0.35, 0.35, 0.35); 
            model.position.set(4.0, -3.5, 0); 

            // Tělo robota natočené směrem k nám
            model.rotation.y = -2.8; 

            scene.add(model);

            const head = model.getObjectByName('Head');
            if (head) {
                headObject = head;
                // Nastavíme výchozí pozici hned při načtení
                head.rotation.set(HEAD_X_OFFSET, HEAD_Y_OFFSET, 0);
            }

            if (gltf.animations.length > 0) {
                mixer = new THREE.AnimationMixer(model);
                const action = mixer.clipAction(gltf.animations[0]);
                action.timeScale = 1.2; 
                action.play();
            }
        });

        const mouse = new THREE.Vector2();
        const windowHalf = new THREE.Vector2(window.innerWidth / 2, window.innerHeight / 2);

        const handleMouseMove = (event) => {
            mouse.x = (event.clientX - windowHalf.x) / windowHalf.x;
            mouse.y = (event.clientY - windowHalf.y) / windowHalf.y;
        };
        document.addEventListener('mousemove', handleMouseMove);

        const clock = new THREE.Clock();
        let animationId;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const delta = clock.getDelta();

            if (mixer) mixer.update(delta);

            if (headObject) {
                // Cílová rotace se počítá od našeho OFFSETU
                const targetRotY = HEAD_Y_OFFSET + (mouse.x * LOOK_LIMIT);
                const targetRotX = HEAD_X_OFFSET + (mouse.y * LOOK_LIMIT);

                // Lerp (plynulý dojezd)
                headObject.rotation.y += (targetRotY - headObject.rotation.y) * 0.1;
                headObject.rotation.x += (targetRotX - headObject.rotation.x) * 0.1;
            }

            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            document.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            if (currentRef) currentRef.removeChild(renderer.domElement);
            renderer.dispose();
        };
    }, []);

    return (
        <div 
            ref={mountRef} 
            style={{ 
                width: '100%', 
                height: '100vh', 
                position: 'fixed',
                top: 0,
                left: 0,
                zIndex: 0,
                pointerEvents: 'none'
            }} 
        />
    );
};

export default RobotScene;
